import json,hashlib
p='/workspace/scratch/volume4/batch409-418.json';d=json.load(open(p))
def page(n,rows):
 ps=[]
 for i,(ar,ru) in enumerate(rows,1):
  sid=f'v4-p{n}-{i:02}';ps.append(dict(id=sid,ar=ar,sha256=hashlib.sha256(ar.encode()).hexdigest(),witness='uploaded_2019_control_pdf',source_complete=True))
  d['units'].append(dict(id=sid+'-ru',source_ids=[sid],printed_pages=[n],ar=ar,ru=ru,draft_status='draft',print_collation='control_image_read',independent_human_review=False))
 d['pages'].append(dict(printed_page=n,pdf_leaf=n,witness_status='control_print_visually_read',publisher_footnote_text_imported=False,paragraphs=ps))
page(416,[
('الحال قال أبو يزيد: «سبحاني» و«ما في الجبة إلا الله»، ونحو ذلك، فأخذ قوم هذه الشطحات، فجعلوها غاية يجرون إليها، ويعملون عليها. فالشيخ شرط أنه لا يثبت شهود الجمع إلا لمن تمكن في شهود طور البقاء.', 'состоянии Абу Язид сказал: «Пречист я» и «Под этой одеждой нет никого, кроме Аллаха», — и тому подобное. Некоторые люди взяли эти экстатические изречения и сделали их целью, к которой устремляются и ради которой действуют. Шейх же поставил условие: созерцание собранности становится устойчивым лишь у того, кто утвердился в созерцании ступени пребывания.'),
('قوله: «والتنافي من الإحساس بالاعتلال». الاعتلال عندهم: هو التفرقة في الأسباب، والوقوف مع الربط الواقع بين المسببات وأسبابها؛ وذلك عقد لا يحله إلا شهود الجمع. ولا يخفى ما في هذه العبارة من العجمة والتعقيد.', 'Его слова «и удаления от ощущения связанности причинами»: под связанностью причинами они понимают разделённое восприятие причин и остановку на существующей связи между следствиями и их причинами. Это узел, который развязывает лишь созерцание собранности. Не скрыто, сколько в этом выражении неясности и сложности.'),
('وكذلك قوله: «والتنافي من شهود شهودها». ومراده: أن يفنى عنه شهود هذه الأشياء التي ذكرها كلها، وأن يفنى عن هذا الشهود. فإنه إن لم يفن عنها كلها وعن شهود فنائه وإلا فهو معها، لأنه يحس بها، ولا يقع الإحساس إلا بما هو موجود عند صاحب الإحساس. فإذا غاب عن شهودها ثم عن شهود الشهود فقد استقر قدمه في حضرة الجمع.', 'То же относится к словам «и удаления от созерцания её созерцания». Он имеет в виду: созерцание всех упомянутых им вещей должно исчезнуть из восприятия человека, а затем должно исчезнуть и осознание этого созерцания. Если он не достигает фана по отношению ко всем им и к созерцанию собственного фана, он остаётся с ними, поскольку ощущает их. А ощущение относится лишь к тому, что присутствует для ощущающего. Когда же он перестаёт сознавать их созерцание, а затем и созерцание самого созерцания, его стопа прочно утверждается в присутствии собранности.'),
('وقد تقدم غير مرة أن هذا ليس بكمال ولا مقصود في نفسه، ولا يعطي كمالا، ولا فيه معرفة، ولا عبودية، ولا دعت إليه الرسل البتة، ولا أشار إليه القرآن، ولا وصفه أئمة أهل الطريق المتقدمون. وغايته أن يشبه صاحبه', 'Уже не раз говорилось, что это не совершенство и не самостоятельная цель, оно не даёт совершенства, не содержит ни познания, ни поклонения. Посланники совершенно не призывали к нему, Коран на него не указывал, ранние имамы людей духовного пути его не описывали. В лучшем случае такой человек подобен')])
page(417,[
('بالغائب عن عقله وحسه وإدراكه. وغايته أن يكون عارضا من عوارض الطريق ليس بلازم، فضلا عن أن يكون غاية.', 'тому, кто утратил разум, чувство и восприятие. Самое большее — это одно из необязательных привходящих состояний пути, тем более оно не является целью.'),
('ولما جعله من جعله غاية مطلوبة يشمر إليها السالكون دخل بسبب ذلك من الفساد على من شمر إليه ما يعلمه الراسخون في العلم من أئمة هذا الشأن. والله المستعان. والعبودية المطلوبة من العبد بمعزل عن ذلك. وبالله التوفيق.', 'Когда некоторые сделали его искомой целью, к которой должны усердно стремиться идущие, это принесло устремившимся к нему столь много порчи, что её знают утвердившиеся в знании имамы этого дела. У Аллаха просят помощи. Требуемое от раба поклонение далеко от этого. Аллах дарует содействие.'),
('قوله: «وهو على ثلاث درجات: جمع علم، ثم جمع وجود، ثم جمع عين. فأما جمع العلم: فهو تلاشي علوم الشواهد في العلم اللدني صرفا. وأما جمع الوجود: فهو تلاشي نهاية الاتصال في عين الوجود محقا. وأما جمع العين: فهو تلاشي كل ما تقله الإشارة في ذات الحق حقا».', 'Его слова: «Она имеет три степени: собранность знания, затем собранность бытия, затем собранность непосредственного созерцания. Собранность знания — исчезновение знаний свидетельств в чистом знании от Него. Собранность бытия — полное исчезновение предела соединения в самом бытии. Собранность непосредственного созерцания — действительное исчезновение всего, что вмещает указание, в Сущности Истинного».'),
('علوم الشواهد: هي ما حصلت من الاستدلال بالأثر على المؤثر، وبالمصنوع على الصانع. فالمصنوعات شواهد وأدلة وآثار، وعلوم الشواهد هي المستندة إلى الشواهد الحاصلة عنها. والعلم اللدني: هو العلم الذي يقذفه الله في القلب إلهاما بلا سبب من العبد ولا استدلال، ولذلك سمي لدنيا. قال الله تعالى: {وعلمناه من لدنا علما} [الكهف: ٦٥]. والله تعالى هو الذي علم العباد ما لم يعلموا، كما قال تعالى: {علم الإنسان ما لم يعلم} [العلق: ٥]. ولكن هذا العلم أخص من غيره، ولذلك أضافه إليه سبحانه، كبيته وناقته وبلده وعبده ونحو ذلك: فتضمحل العلوم المستندة إلى الأدلة', 'Знания свидетельств — это знания, полученные посредством заключения от следа к Тому, Кто его оставил, от сотворённого — к Творцу. Сотворённые вещи — свидетельства, доказательства и следы; знания свидетельств опираются на свидетельства и происходят от них. Знание от Него — аль-‘ильм аль-лядунни — это знание, которое Аллах влагает в сердце как внушение, без причины со стороны раба и без умозаключения. Поэтому оно и названо знанием от Него. Всевышний Аллах сказал: {وعلمناه من لدنا علما} — «И научили его знанию от Нас» [18:65]. Всевышний Аллах — Тот, Кто научил рабов тому, чего они не знали, как Он сказал: {علم الإنسان ما لم يعلم} — «Научил человека тому, чего тот не знал» [96:5]. Однако это знание более особое, чем другое, потому Пречистый и отнёс его к Себе, как Свой Дом, Свою верблюдицу, Свой город, Своего раба и тому подобное. Итак, знания, опирающиеся на доказательства, исчезают')])
page(418,[
('والشواهد في العلم اللدني الحاصل بلا سبب ولا استدلال. هذا مضمون كلامه.', 'и свидетельства, в знании от Него, полученном без причины и без умозаключения. Таков смысл его слов.'),
('ونحن نقول: إن العلم الحاصل بالشواهد والأدلة هو العلم الحقيقي. وأما ما يدعى حصوله بغير شاهد ولا دليل، فلا وثوق به، وليس بعلم. نعم، قد يقوى العلم الحاصل بالشواهد ويتزايد، بحيث يصير المعلوم كالمشهود، والغائب كالمعاين، وعلم اليقين كعين اليقين: فيكون الأمر شعورا أولا، ثم تجويزا، ثم ظنا، ثم علما، ثم معرفة، ثم علم يقين، ثم عين يقين؛ وتضمحل كل مرتبة في التي فوقها بحيث يصير الحكم لها دونها. فهذا حق.', 'Мы же говорим: знание, полученное посредством свидетельств и доказательств, — подлинное знание. А тому, что, как утверждают, получено без свидетельства и доказательства, нельзя доверять: это не знание. Да, знание, полученное посредством свидетельств, может усиливаться и возрастать, так что познаваемое становится словно созерцаемым, сокрытое — словно видимым воочию, а знание убеждённости — словно непосредственная убеждённость. Вначале бывает ощущение, затем допущение возможности, затем предположение, затем знание, затем познание, затем знание убеждённости и затем непосредственная убеждённость. Каждая ступень исчезает в той, что выше неё, так что определяющей становится высшая, а не низшая. Это верно.'),
('وأما دعوى وقوع نوع من العلم بغير سبب ولا استدلال، فليس بصحيح، فإن الله سبحانه ربط التعريفات بأسبابها، كما ربط الكائنات بأسبابها، ولا يحصل لبشر علم إلا بدليل يدله عليه. وقد أيد الله رسله بأنواع الأدلة والبراهين التي دلتهم على أن ما جاءهم هو من عند الله، ودلت أممهم على ذلك، وكان معهم أعظم الأدلة والبراهين على أن ما جاءهم هو من عند الله، وكانت براهينهم أدلة وشواهد لهم وللأمم. فالأدلة والشواهد التي كانت لهم ومعهم أعظم الشواهد الأدلة، والله تعالى شهد بتصديقهم بما أقام عليه من الشواهد. فكل علم لا يستند إلى دليل فدعوى لا دليل عليها، وحكم لا برهان عند قائله؛ وما كان كذلك لم يكن علما، فضلا عن أن يكون لدنيا.', 'Утверждение же, что некий вид знания возникает без причины и умозаключения, неверно. Пречистый Аллах связал даруемые познания с их причинами, как связал существующие вещи с их причинами. Человек обретает знание лишь посредством доказательства, которое указывает ему на него. Аллах подкрепил Своих посланников различными доказательствами и доводами, показавшими им, что пришедшее к ним — от Аллаха, и показавшими это их общинам. У них были величайшие доказательства и доводы того, что пришедшее к ним — от Аллаха. Их доводы служили доказательствами и свидетельствами и для них самих, и для общин. Доказательства и свидетельства, которые они имели и которые сопровождали их, — величайшие свидетельства и доказательства. Всевышний Аллах засвидетельствовал их правдивость посредством установленных Им свидетельств. Всякое знание, не опирающееся на доказательство, — бездоказательное притязание и суждение, для которого у говорящего нет довода. Такое не является знанием, тем более знанием от Него.')])
json.dump(d,open(p,'w'),ensure_ascii=False,indent=2)
